add_action( 'woocommerce_account_dashboard', 'perfectpixel_cross_sells_on_dashboard', 20 );
add_action( 'woocommerce_order_status_changed', 'perfectpixel_cross_sells_on_dashboard_flush', 10, 4 );

function perfectpixel_cross_sells_on_dashboard() {
	$user_id = get_current_user_id();
	$key     = 'perfectpixel_account_xsells_' . $user_id;
	$ids     = get_transient( $key );
	if ( false === $ids ) {
		$bought = array();
		$ids    = array();
		foreach ( wc_get_orders( array( 'customer' => $user_id, 'status' => wc_get_is_paid_statuses(), 'limit' => 100 ) ) as $order ) {
			foreach ( $order->get_items() as $item ) {
				$bought[] = (int) $item->get_product_id();
				$product  = wc_get_product( $item->get_product_id() );
				if ( $product ) {
					$ids = array_merge( $ids, $product->get_cross_sell_ids() );
				}
			}
		}
		$ids = array_values( array_diff( array_unique( array_map( 'intval', $ids ) ), $bought ) );
		set_transient( $key, $ids, 12 * HOUR_IN_SECONDS );
	}
	$ids = array_slice( (array) $ids, 0, max( 1, (int) '{{account_crosssells_limit}}' ) );
	if ( $ids ) {
		echo '<h2>' . esc_html( '{{account_crosssells_title}}' ) . '</h2>';
		echo do_shortcode( '[products ids="' . esc_attr( implode( ',', $ids ) ) . '" columns="' . count( $ids ) . '" orderby="post__in"]' );
	}
}

function perfectpixel_cross_sells_on_dashboard_flush( $order_id, $from, $to, $order ) {
	if ( $order && $order->get_customer_id() ) {
		delete_transient( 'perfectpixel_account_xsells_' . $order->get_customer_id() );
	}
}
